470183.Script:
.@r = getrefine();
.@g = getenchantgrade();
bonus bAllStats,2;
bonus bMdef,15;
bonus bMaxHPrate,15;
bonus bMaxSPrate,5;
if (.@r>=10) {
   if (readparam(bStr)>=108)
       bonus bBaseAtk,80;
   if (readparam(bAgi)>=108)
       bonus bAspd,2;
   if (readparam(bVit)>=108)
       bonus bMaxHPrate,10;
   if (readparam(bInt)>=108)
       bonus bMatk,80;
   if (readparam(bDex)>=108) {
       bonus bFixedCast,-500;
       bonus bLongAtkRate,10;
   }
   if (readparam(bLuk)>=108)
       bonus bCritAtkRate,35;
}
if (.@r>=13) {
   if (readparam(bPow)>=60)
       bonus2 bAddSize,Size_All,15;
   if (readparam(bSta)>=60) {
       bonus bDelayrate,-5;
       bonus bPAtk,15;
   }
   if (readparam(bWis)>=60) {
       bonus bDelayrate,-5;
       bonus bSMatk,15;
   }
   if (readparam(bSpl)>=60)
       bonus2 bMagicAddSize,Size_All,15;
   if (readparam(bCon)>=60)
       bonus bAspdRate,10;
   if (readparam(bCrt)>=60) {
       bonus bFixedCast,-200;
       bonus bCritAtkRate,10;
   }
}
if (.@g>=ENCHANTGRADE_D) {
   bonus bRes,30;
   bonus bMRes,30;
}
if (.@g>=ENCHANTGRADE_C) {
   bonus bBaseAtk,50;
   bonus bMatk,50;
}
if (.@g>=ENCHANTGRADE_B) {
   bonus2 bAddRace,RC_All,15;
   bonus2 bMagicAddRace,RC_All,15;
}
if (.@g>=ENCHANTGRADE_A) {
   bonus bPAtk,7;
   bonus bSMatk,7;
}

